  function arithmagonSVG(a,answers){const coords=a.shape==='square'?[[18,18],[82,18],[82,82],[18,82]]:[[50,10],[88,82],[12,82]],corners=answers?a.corners:a.displayCorners,edges=answers?a.edges:a.displayEdges;let lines='',nodes='';for(let i=0;i<coords.length;i++){const p=coords[i],q=coords[(i+1)%coords.length],mx=(p[0]+q[0])/2,my=(p[1]+q[1])/2;lines+=`<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}"/>`;nodes+=`<g class="edge"><circle cx="${mx}" cy="${my}" r="8"/><text x="${mx}" y="${my+2.7}">${edges[i]==null?'?':esc(edges[i])}</text></g>`;}coords.forEach((p,i)=>nodes+=`<g class="corner"><circle cx="${p[0]}" cy="${p[1]}" r="9"/><text x="${p[0]}" y="${p[1]+3}">${corners[i]==null?'?':esc(corners[i])}</text></g>`);return `<svg class="tt99-arithmagon-svg" viewBox="0 0 100 100" aria-label="Arithmagon">${lines}${nodes}</svg>`;}
