  function magicShapeSVG(a,answers){const vals=answers&&a.puzzleType!=='check'?a.solutionValues:a.displayValues;let lines='',nodes='';for(const line of a.lines||[]){const p=a.coords[line[0]],q=a.coords[line.at(-1)];lines+=`<line x1="${p[0]*100}" y1="${p[1]*100}" x2="${q[0]*100}" y2="${q[1]*100}"/>`;}a.coords.forEach((p,i)=>nodes+=`<g class="node ${answers&&a.brokenIndex===i?'bad':''}"><circle cx="${p[0]*100}" cy="${p[1]*100}" r="5.8"/><text x="${p[0]*100}" y="${p[1]*100+2.3}">${vals[i]==null?'?':esc(vals[i])}</text></g>`);return `<svg class="tt99-magicshape-svg" viewBox="-5 -5 110 110">${lines}${nodes}</svg>`;}
