  function renderCrossnumber(a,answers,index,si,ai){const starts=new Map();for(const e of a.entries||[]){const k=`${e.x}:${e.y}`;if(!starts.has(k))starts.set(k,e.number);}const cells=a.grid.flatMap((row,y)=>row.map((ch,x)=>{if(!ch)return '';const n=starts.get(`${x}:${y}`);return `<span class="open" style="grid-column:${x+1};grid-row:${y+1}">${n?`<i>${n}</i>`:''}${answers?`<b>${ch}</b>`:''}</span>`;}).join('')).join(''),across=a.entries.filter(e=>e.dir==='across'),down=a.entries.filter(e=>e.dir==='down'),clues=(label,list)=>`<div class="tt99-crossword-clue-group"><h4>${label}</h4><ol>${list.map(e=>`<li value="${e.number}">${esc(e.clue)}</li>`).join('')}</ol></div>`;return `<section class="tt99-game-activity tt99-crossnumber">${activityReplaceButton(si,ai)}${arithmeticHead(a,index)}<div class="tt99-crossword-layout"><div class="tt99-crossword-grid" style="--cw:${a.width};--ch:${a.height}">${cells}</div><div class="tt99-crossword-clues">${clues('Across',across)}${clues('Down',down)}</div></div></section>`;}

