    for(let i=0;i<n;i++){const ang=-Math.PI/2+i*2*Math.PI/n,ix=cx+Math.cos(ang)*innerR,iy=cy+Math.sin(ang)*innerR,ox=cx+Math.cos(ang)*outerR,oy=cy+Math.sin(ang)*outerR,out=answers?item.outputs[i]:(item.displayOutputs[i]??'?');marks+=`<line x1="${ix}" y1="${iy}" x2="${ox}" y2="${oy}"/><g class="inner"><circle cx="${ix}" cy="${iy}" r="10"/><text x="${ix}" y="${iy+3}">${esc(item.inputs[i])}</text></g><g class="outer ${out==='?'?'blank':''}"><circle cx="${ox}" cy="${oy}" r="11"/><text x="${ox}" y="${oy+3}">${esc(out)}</text></g>`;}
