    return `<svg class="tt99-factor-svg" viewBox="0 0 160 160" aria-label="Factor flower">${petals}<g class="centre"><circle cx="80" cy="80" r="23"/><text x="80" y="77">FACTORS OF</text><text x="80" y="91">${esc(item.centre)}</text></g></svg>`;
